<script setup lang="ts">
import {ref,reactive,computed,watch,onUnmounted} from 'vue'
import {useAuthStore} from '../../../stores/auth'
import * as api from '../../../api/adminStatistics'
import type {Window,UsersSummary,PredictionsSummary,TasksSummary,MarketSummary,HttpSummary} from '../../../api/adminStatistics'
import {defaultWindow,validateWindow,number,time,taskLabels,httpLabels} from './statisticsPresentation'
import StatisticsQueryForm from './StatisticsQueryForm.vue'
import StatisticsSection from './StatisticsSection.vue'
import StatisticsChart from './StatisticsChart.vue'
const auth=useAuthStore(),applied=ref<Window>(defaultWindow()),busy=ref(false),denied=ref(false),queryError=ref(''),marketPage=ref(1)
type Key='users'|'predictions'|'tasks'|'market'|'http'
interface Section {data:unknown|null;busy:boolean;error:string;stale:boolean}
const keys:Key[]=['users','predictions','tasks','market','http']
const sections=reactive<Record<Key,Section>>(Object.fromEntries(keys.map(k=>[k,{data:null,busy:false,error:'',stale:false}])) as Record<Key,Section>)
const users=computed(()=>sections.users.data as UsersSummary|null),predictions=computed(()=>sections.predictions.data as PredictionsSummary|null),tasks=computed(()=>sections.tasks.data as TasksSummary|null),market=computed(()=>sections.market.data as MarketSummary|null),http=computed(()=>sections.http.data as HttpSummary|null)
const canRead=computed(()=>auth.profile?.role==='ADMIN'&&!denied.value)
let epoch=0
function identity(){return auth.profile?auth.profile.userId+':'+auth.profile.role:''}
function clear(partitions:Key[]=keys){for(const k of partitions)Object.assign(sections[k],{data:null,busy:false,error:'',stale:false})}
function rejected(error:unknown,n:number,owner:string){const status=(error as {status?:number}|null)?.status;if(n!==epoch||owner!==identity())return true;if(status===401||status===403){denied.value=true;epoch++;clear();busy.value=false;void Promise.resolve().then(()=>auth.refresh()).catch(()=>{});return true}return false}
async function read(k:Key,fetch:()=>Promise<unknown>,n:number,owner:string){sections[k].busy=true;sections[k].error='';try{const value=await fetch();if(n!==epoch||owner!==identity()||!canRead.value)return;sections[k].data=value;sections[k].stale=false}catch(error){if(rejected(error,n,owner))return;sections[k].error=(error as {message?:string}|null)?.message||'本区暂不可用，请稍后刷新';sections[k].stale=sections[k].data!==null}finally{if(n===epoch)sections[k].busy=false}}
async function refresh(){if(!canRead.value||busy.value)return;const n=++epoch,owner=identity(),window={...applied.value};busy.value=true;await Promise.allSettled([read('users',()=>api.getUsers(window),n,owner),read('predictions',()=>api.getPredictions(window),n,owner),read('tasks',()=>api.getTasks(window),n,owner),read('market',()=>api.getMarket(window,marketPage.value,20),n,owner),read('http',()=>api.getHttp(),n,owner)]);if(n===epoch)busy.value=false}
function apply(window:Window){if(busy.value)return;queryError.value=validateWindow(window);if(queryError.value)return;if(window.from!==applied.value.from||window.to!==applied.value.to){clear(['users','predictions','tasks','market']);marketPage.value=1;applied.value={...window}}void refresh()}
async function marketMove(page:number){if(!canRead.value||busy.value||page<1)return;const n=++epoch,owner=identity();busy.value=true;await read('market',()=>api.getMarket({...applied.value},page,20),n,owner);if(n===epoch){if(!sections.market.error)marketPage.value=page;busy.value=false}}
watch([()=>auth.profile?.userId,()=>auth.profile?.role],()=>{epoch++;clear();busy.value=false;denied.value=false;if(canRead.value)void refresh()},{immediate:true,flush:'sync'})
onUnmounted(()=>{epoch++})
</script>
<template><main class="account-wrap stats-workspace"><div class="stats-layout"><header class="stats-page-header"><div><p class="eyebrow">管理员工作区</p><h1>运营统计</h1><p class="hint">了解系统使用与运行情况。所有统计只读，刷新不会发起预测或更新行情。</p></div><button v-if="canRead" type="button" data-test="statistics-refresh" :disabled="busy" @click="refresh">{{busy?'刷新中…':'刷新统计'}}</button></header><p v-if="denied" role="alert" class="stats-error">管理员访问已失效，统计数据已清空。请重新确认账号权限。</p><p v-else-if="!canRead" role="status">仅管理员可以查看运营统计。</p><template v-else><div class="stats-section"><StatisticsQueryForm :window="applied" :busy="busy" @apply="apply"/><p v-if="queryError" role="alert" class="stats-error">{{queryError}}</p><p class="stats-applied">已应用期间：{{applied.from}} 至 {{applied.to}}（上海日期）</p><p class="small">业务区间、当前存量与进程观测分别标注；各服务查询时间可能略有不同。</p></div>
<StatisticsSection data-test="stat-users" title="用户与登录" description="用户规模是当前存量；新增注册与成功登录按所选日期统计。成功登录人数不等于日活或在线人数。" :busy="sections.users.busy" :error="sections.users.error" :stale="sections.users.stale" :queried-at="users?.meta.queriedAt"><template v-if="users"><dl class="stats-kpis"><div><dt>用户总数 · 当前</dt><dd>{{number(users.totalUsers)}}</dd></div><div><dt>启用 / 封禁 · 当前</dt><dd>{{number(users.enabledUsers)}} / {{number(users.disabledUsers)}}</dd></div><div><dt>新增注册 · 期间</dt><dd>{{number(users.registrations)}}</dd></div><div><dt>成功登录次数 · 期间</dt><dd>{{number(users.successfulLogins)}}</dd></div><div><dt>成功登录人数 · 期间去重</dt><dd>{{number(users.distinctLoginUsers)}}</dd></div></dl><p class="small">当前角色：<span v-for="r in users.roleCounts" :key="r.key">{{r.key==='ADMIN'?'管理员':'普通用户'}} {{number(r.count)}}　</span></p><StatisticsChart title="注册与成功登录日趋势" :labels="users.registrationDaily.map(x=>x.date)" :series="[{name:'新增注册',values:users.registrationDaily.map(x=>x.count)},{name:'成功登录次数',values:users.loginDaily.map(x=>x.successfulLogins)},{name:'成功登录人数',values:users.loginDaily.map(x=>x.distinctUsers)}]"/></template></StatisticsSection>
<StatisticsSection data-test="stat-predictions" title="预测与模型版本" description="统计已受理业务请求，包含本人已隐藏记录；按创建日查看当前结果，状态完成后原日期分类会更新。不是实际推理次数或模型准确率。" :busy="sections.predictions.busy" :error="sections.predictions.error" :stale="sections.predictions.stale" :queried-at="predictions?.meta.queriedAt"><template v-if="predictions"><dl class="stats-kpis"><div><dt>已受理预测请求</dt><dd>{{number(predictions.acceptedRequests)}}</dd></div><div v-for="s in predictions.stateCounts" :key="s.key"><dt>{{taskLabels[s.key]??s.key}}</dt><dd>{{number(s.count)}}</dd></div></dl><div class="stats-chart-grid"><StatisticsChart title="预测请求创建日趋势" :labels="predictions.requestDaily.map(x=>x.date)" :series="[{name:'已受理请求',values:predictions.requestDaily.map(x=>x.accepted)},{name:'成功',values:predictions.requestDaily.map(x=>x.succeeded)},{name:'失败',values:predictions.requestDaily.map(x=>x.failed)},{name:'运行中',values:predictions.requestDaily.map(x=>x.running)}]"/><StatisticsChart v-if="predictions.modelUsage.length" title="模型版本使用数量" type="bar" :labels="predictions.modelUsage.map(x=>x.artifactId??x.modelId)" :series="[{name:'受理请求',values:predictions.modelUsage.map(x=>x.acceptedRequests)}]"/></div><p v-if="!predictions.modelUsage.length">模型使用暂无样本。</p><div v-else class="stats-scroll" tabindex="0" role="region" aria-label="模型版本使用表，可横向滚动"><table><thead><tr><th scope="col">模型版本</th><th scope="col">受理请求</th><th scope="col">成功请求</th><th scope="col">使用占比</th></tr></thead><tbody><tr v-for="m in predictions.modelUsage" :key="m.modelId"><th scope="row">{{m.label}}</th><td>{{number(m.acceptedRequests)}}</td><td>{{number(m.successfulRequests)}}</td><td>{{m.usagePercent===null?'暂无样本':m.usagePercent+'%'}}</td></tr></tbody></table></div></template></StatisticsSection>
<StatisticsSection data-test="stat-tasks" title="任务与执行" description="任务按创建日期统计，执行尝试按开始日期统计，两者分母不同。重试保留历史失败，执行耗时包含等待下游，不是算法计算或训练耗时。" :busy="sections.tasks.busy" :error="sections.tasks.error" :stale="sections.tasks.stale" :queried-at="tasks?.meta.queriedAt"><template v-if="tasks"><dl class="stats-kpis"><div><dt>创建任务</dt><dd>{{number(tasks.taskTotal)}}</dd></div><div><dt>执行尝试</dt><dd>{{number(tasks.attemptTotal)}}</dd></div><div><dt>平均尝试耗时</dt><dd>{{tasks.attemptDuration.meanMs===null?'暂无样本':tasks.attemptDuration.meanMs+' ms'}}</dd></div><div><dt>平均首次派发等待</dt><dd>{{tasks.firstQueueWait.meanMs===null?'暂无样本':tasks.firstQueueWait.meanMs+' ms'}}</dd></div></dl><p class="small">耗时有效样本 {{tasks.attemptDuration.sampleCount}}；异常时间剔除 {{tasks.attemptDuration.excludedInvalidCount}}；未结束尝试 {{tasks.unfinishedAttempts}}。首次派发样本 {{tasks.firstQueueWait.sampleCount}}，异常剔除 {{tasks.firstQueueWait.excludedInvalidCount}}。</p><StatisticsChart title="任务状态分布" type="bar" :labels="tasks.taskStateCounts.map(x=>taskLabels[x.key]??x.key)" :series="[{name:'任务数',values:tasks.taskStateCounts.map(x=>x.count)}]"/><div class="stats-tag-list"><p v-for="t in tasks.taskTypeCounts" :key="t.key">{{taskLabels[t.key]??t.key}}：{{number(t.count)}}</p></div><details><summary>查看执行尝试状态</summary><p v-for="s in tasks.attemptStateCounts" :key="s.key">{{taskLabels[s.key]??s.key}}：{{number(s.count)}}</p></details><a href="/admin/tasks">查看任务工作区</a></template></StatisticsSection>
<StatisticsSection data-test="stat-market" title="行情当前状态" description="展示当前发布头，不是所选日期的历史快照。检查时间、取数时间和行情覆盖日期分别显示；无数据不会补造日期。" :busy="sections.market.busy" :error="sections.market.error" :stale="sections.market.stale" :queried-at="market?.meta.queriedAt"><template v-if="market"><dl class="stats-kpis"><div><dt>有可用头的股票</dt><dd>{{number(market.instrumentCount)}}</dd></div><div><dt>可用发布头 · 按来源</dt><dd>{{number(market.availableHeads)}}</dd></div></dl><div v-if="market.items.length" class="stats-scroll" tabindex="0" role="region" aria-label="行情当前发布状态，可横向滚动"><table><thead><tr><th scope="col">股票 / 来源</th><th scope="col">状态</th><th scope="col">行情覆盖至</th><th scope="col">最近检查</th><th scope="col">取数 / 发布时间</th><th scope="col">版本与质量</th></tr></thead><tbody><tr v-for="m in market.items" :key="m.instrumentId+':'+m.provider+':'+m.priceBasis"><th scope="row">{{m.instrumentId}}<br/>{{m.provider??'尚无数据源头'}} {{m.priceBasis??''}}</th><td>{{m.status??'尚无数据'}}<br/>{{m.lastErrorCode??''}}</td><td>{{m.coverageEnd??'暂无数据'}}</td><td>{{time(m.checkedAt)}}</td><td>{{time(m.fetchedAt)}}<br/>{{time(m.publishedAt)}}</td><td><details><summary>查看版本</summary><p>{{m.versionId??'暂无版本'}}</p><p>{{m.quality??'暂无质量记录'}}</p></details></td></tr></tbody></table></div><p v-else>暂无股票发布状态。</p><div class="stats-pager"><button type="button" :disabled="busy||marketPage===1" @click="marketMove(marketPage-1)">上一页行情</button><span>第 {{marketPage}} 页</span><button type="button" data-test="market-next" :disabled="busy||!market.hasMore" @click="marketMove(marketPage+1)">下一页行情</button></div></template></StatisticsSection>
<StatisticsSection data-test="stat-http" title="网关响应观测" description="仅统计当前网关进程完成的HTTP请求，包含等待下游；HTTP错误率不是预测失败率。重启清零，与上方日期筛选无关。统计自身访问不计数。" :busy="sections.http.busy" :error="sections.http.error" :stale="sections.http.stale" :queried-at="http?.queriedAt"><template v-if="http"><p class="small">进程启动：{{time(http.processStartedAt)}}；开始观测：{{time(http.observedSince)}}。未完成或无法确认的样本：{{number(http.droppedSamples)}}。</p><div class="stats-scroll" tabindex="0" role="region" aria-label="网关响应统计，可横向滚动"><table><thead><tr><th scope="col">接口组</th><th scope="col">完成请求</th><th scope="col">HTTP 4xx</th><th scope="col">HTTP 5xx</th><th scope="col">平均响应</th><th scope="col">HTTP错误率</th></tr></thead><tbody><tr v-for="g in http.groups" :key="g.group"><th scope="row">{{httpLabels[g.group]??g.group}}</th><td>{{number(g.completedRequests)}}</td><td>{{number(g.http4xx)}}</td><td>{{number(g.http5xx)}}</td><td>{{g.meanDurationMs===null?'暂无样本':g.meanDurationMs+' ms'}}</td><td>{{g.errorPercent===null?'暂无样本':g.errorPercent+'%'}}</td></tr></tbody></table></div></template></StatisticsSection>
</template></div></main></template>
<style>
.stats-layout{max-width:1180px;margin:auto}.stats-page-header{display:flex;justify-content:space-between;gap:24px;align-items:flex-start}.stats-page-header h1{margin:4px 0 12px;font-size:30px}.stats-workspace button,.stats-workspace summary{font:inherit;min-height:44px;cursor:pointer}.stats-workspace button{padding:8px 16px;border:1px solid var(--border);border-radius:8px;background:var(--surface);color:var(--accent)}.stats-workspace button:disabled{opacity:.6;cursor:default}.stats-workspace :focus-visible{outline:3px solid var(--accent);outline-offset:3px}.stats-section{background:var(--surface);padding:26px;border:1px solid var(--border);border-radius:12px;margin-bottom:24px;min-width:0}.stats-section header{display:flex;justify-content:space-between;align-items:center;gap:16px}.stats-section h2{margin:0;font-size:22px}.stats-description,.stats-time{color:var(--muted)}.stats-description{margin:10px 0}.stats-time{margin:0 0 18px}.stats-quick,.stats-dates,.stats-pager{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.stats-dates{margin-top:16px;align-items:flex-end}.stats-dates label{display:flex;flex-direction:column;gap:6px}.stats-dates input{font:inherit;min-height:44px;background:var(--surface);border:1px solid var(--border);border-radius:6px;color:var(--ink);padding:8px}.stats-applied{font-weight:600}.stats-kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:16px;margin:22px 0}.stats-kpis>div{padding:16px;background:var(--canvas);border-radius:8px;min-width:0}.stats-kpis dt{font-size:14px;color:var(--muted)}.stats-kpis dd{margin:8px 0 0;font-size:23px;line-height:1.4;font-weight:600;overflow-wrap:anywhere}.stats-chart-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}.stats-figure{margin:22px 0;min-width:0}.stats-figure figcaption{font-weight:600;margin:0 0 12px}.stats-chart{height:260px;min-width:0}.stats-scroll{overflow-x:auto;max-width:100%;margin:14px 0}.stats-scroll table{border-collapse:collapse;min-width:520px;width:100%;text-align:left;font-size:14px}.stats-scroll th,.stats-scroll td{padding:12px;border-bottom:1px solid var(--border);vertical-align:top;overflow-wrap:anywhere;max-width:280px}.stats-scroll thead{background:var(--canvas)}.stats-scroll th{font-weight:600}.stats-scroll details p{min-width:160px}.stats-pager{margin-top:18px}.stats-error{padding:12px;background:#fff0f0;color:#a21c23;border-radius:6px}.stats-stale{padding:12px;background:#fff6e7;color:#754500;border-radius:6px}.stats-tag-list{display:flex;flex-wrap:wrap;gap:16px}.stats-tag-list p{margin:6px 0}.stats-section details{margin:12px 0}.stats-section summary{padding:8px 0}.stats-section a{display:inline-flex;align-items:center;min-height:44px;margin-top:12px}@media(max-width:760px){.stats-chart-grid{grid-template-columns:1fr}.stats-section{padding:20px 16px}.stats-page-header{flex-direction:column;gap:0}.stats-page-header>button{margin-bottom:22px}.stats-dates{align-items:stretch}.stats-dates label{flex:1;min-width:140px}.stats-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}.stats-kpis dd{font-size:20px}}@media(max-width:380px){.stats-kpis{grid-template-columns:1fr}}
</style>
